            "id": "w1",
            "statement": "2026년 6월30일 마감 2분기(FY26 Q2) 매출이 1억6,884.7만달러로 전년동기 대비 +55.2% 증가했고, 영업이익률이 직전분기 -12.5%에서 -2.5%로 10.0%p 개선되며 순이익이 176만달러(YoY +106.6%)로 흑자전환했다. 컨센서스를 상회한 이 실적 서프라이즈가 랠리의 1차 트리거로 작용했다.",
