        "company": "ServiceNow는 ITSM(IT서비스관리)에서 출발해 HR, 고객서비스, 보안·리스크 관리로 워크플로우 자동화 플랫폼을 확장한 엔터프라이즈 SaaS 기업으로, 매출 대부분이 구독형 반복매출이다. 최근 분기(2026-06-30 종료) 매출 $39.87억(YoY +24%)를 기록했으며, Now Assist·AI Control Tower를 앞세운 에이전틱 AI 상위 SKU 판매와 기존 고객 업셀링이 성장의 축이다. 갱신 고객의 첫 Agentic AI 구매 비중이 QoQ·YoY 2배 확대되는 등 동일 고객 기반 내 계약가치 확장(업셀링) 국면이 진행 중이다.",
        "lead": "ServiceNow(NOW)는 최근 1개월 절대 상승률 14.8%, 3개월 49.09%를 기록하며 RS 상위 1M 1.7% 구간에 진입했고 200일선 대비 20.76% 괴리된 상태에서 강세를 지속하고 있다. 9월 들어 AI Control Tower 전략과 에이전틱 AI 채택 확산을 다루는 뉴스가 연이어 게재됐고, 직전 2Q26(2026-06-30 종료) 실적에서 매출과 구독 가이던스가 컨센서스를 상회한 점이 랠리의 배경으로 제시된다.",
